import json
import os
import urllib.parse
import urllib.request

BASE = os.environ.get(
    "PRICING_BASE_URL", "http://pricing-v2.internal:8081/api/v2/price"
)


def get_price(sku: str) -> float:
    url = f"{BASE}/{urllib.parse.quote(sku, safe='')}"
    headers = {}
    if api_key := os.environ.get("PRICING_KEY"):
        headers["X-Pricing-Key"] = api_key
    with urllib.request.urlopen(urllib.request.Request(url, headers=headers), timeout=5) as r:
        return float(json.load(r)["price"])


def get_total(skus: list) -> float:
    return sum(get_price(sku) for sku in skus)
